return {
  focus: {
    hook: "onEvent",
    eventType: "guard",
    promptOnPlayer: async (H, actor) => {
      const allies = H.zone.allies(actor);
      if (!allies.length) return false;
      const targetId = await H.ask.one({
        title: "Rally",
        label: "Rally",
        options: allies.map(ally => ({ value: ally.id, label: ally.name })),
        applyLabel: "Focus Ally",
      });
      if (!targetId) return false;
      const target = game.actors.get(targetId);
      await H.actions.grantManoeuvre(target, "focus");
      return true;
    },
  },
};
